// The list the machine works through, top to bottom. Add, remove or reorder freely.
// style: "long" = 9 takes, 4-5 places, about 70 s.  "short" = 6 takes, studio + 2 places, about 45 s.
// A topic that already has a finished episode is skipped.
const topics = [
  {
    "topic": "Why the ocean is salty when the rivers that feed it are fresh",
    "where": "a rocky ocean beach; a river mouth or stream running over rocks",
    "style": "short"
  },
  {
    "topic": "How honey bees turn flower nectar into honey",
    "where": "a flower garden beside wooden beehive boxes; a kitchen counter with a jar of honey and honeycomb",
    "style": "short"
  },
  {
    "topic": "How a volcano erupts",
    "where": "a field of black hardened lava rock; the rim of an old volcanic crater",
    "style": "short"
  },
  {
    "topic": "Why leaves change color in autumn",
    "where": "a forest path under red and yellow maple trees; beside a single bright tree with fallen leaves on the ground",
    "style": "short"
  },
  {
    "topic": "Why the sea has tides",
    "where": "a rocky shore with tide pools at low tide; a harbor wall with a visible high-water line",
    "style": "short"
  },
  {
    "topic": "How glaciers carve valleys",
    "where": "a wide U-shaped mountain valley; beside a huge smooth scratched boulder left by ice",
    "style": "short"
  },
  {
    "topic": "How trees share food and warnings through fungus in the soil",
    "where": "an old mossy forest among big tree roots; beside a fallen log covered in mushrooms",
    "style": "short"
  },
  {
    "topic": "Why ice floats on water",
    "where": "the edge of a frozen lake; a kitchen counter with a clear glass of ice water",
    "style": "short"
  },
  {
    "topic": "How sand dunes move",
    "where": "among tall desert sand dunes with wind ripples; the sharp crest of a dune",
    "style": "short"
  },
  {
    "topic": "How caves grow stalactites",
    "where": "the mouth of a limestone cave; inside a lit cave with stalactites behind her",
    "style": "short"
  },
  {
    "topic": "How a river carves a canyon",
    "where": "the rim of a deep red-rock canyon; down by the river at the canyon floor",
    "style": "short"
  },
  {
    "topic": "Why the desert gets cold at night",
    "where": "a rocky desert with cactus in daylight; the same desert under an overcast sky",
    "style": "short"
  },
  {
    "topic": "How coral reefs are built by tiny animals",
    "where": "a tropical beach beside clear shallow water with reef visible; an aquarium wall with living coral behind her",
    "style": "short"
  },
  {
    "topic": "How mountains make their own weather",
    "where": "a mountain meadow with clouds piling against peaks; a dry rocky slope on the far side of a range",
    "style": "short"
  },
  {
    "topic": "Why rivers bend and wind instead of running straight",
    "where": "a grassy bank above a winding river; the inside of a river bend with a gravel bar",
    "style": "short"
  },
  {
    "topic": "How a seed knows which way is up",
    "where": "a vegetable garden with seedlings in rows; a greenhouse bench with sprouting pots",
    "style": "short"
  },
  {
    "topic": "How a waterfall slowly moves backward up its river",
    "where": "the pool at the foot of a waterfall; the flat river above the drop; a narrow rock gorge downstream; a mossy cliff beside the falls",
    "style": "long"
  },
  {
    "topic": "Where the sand on a beach comes from",
    "where": "a wide sandy beach; a rocky headland with waves breaking; a river mouth carrying brown water to the sea; a dune with grass behind the beach",
    "style": "long"
  },
  {
    "topic": "Why some cliffs have stripes: how rock layers are laid down",
    "where": "the foot of a striped layered cliff; a dry riverbed with flat stones; a canyon wall of red and cream bands; a muddy lake shore where new layers settle",
    "style": "long"
  },
  {
    "topic": "How a forest grows back after a fire",
    "where": "blackened standing trunks with green shoots at their feet; a meadow of purple flowers among burnt logs; young pines in rows of natural regrowth; an old unburnt forest edge",
    "style": "long"
  },
  {
    "topic": "How a river is born: from a spring on a hill to the sea",
    "where": "a spring bubbling out of a mossy hillside; a small rocky mountain stream; a wide slow lowland river; a river mouth at the coast",
    "style": "long"
  },
  {
    "topic": "How geysers and hot springs work",
    "where": "a steaming blue hot spring pool; white mineral terraces; a geyser cone venting steam; a boardwalk-free field of steaming ground",
    "style": "long"
  },
  {
    "topic": "How soil is made from rock",
    "where": "bare grey rock covered in lichen; a rocky slope with thin grass; a forest floor of dark leaf litter; a cut bank showing soil layers above rock",
    "style": "long"
  },
  {
    "topic": "How fog forms and why it sits in valleys",
    "where": "a hilltop above a valley filled with fog; a misty lake shore; a foggy pine forest; a clear meadow after the fog lifts",
    "style": "long"
  },
  {
    "topic": "How a wetland cleans water",
    "where": "a marsh of tall reeds; a still pond covered in lily pads; a muddy channel between grasses; clear water leaving the wetland over stones",
    "style": "long"
  },
  {
    "topic": "How to read a tree's life in its rings",
    "where": "a large sawn tree stump with clear rings; an old forest of thick trunks; a young sapling grove; a fallen log split open",
    "style": "long"
  },
  {
    "topic": "Why waves break when they reach the shore",
    "where": "a beach with rolling breakers; a rocky point with spray; calm deep water off a cliff; a shallow sandbar at low tide",
    "style": "long"
  }
];
return [{ json: { encoded: Buffer.from(JSON.stringify(topics)).toString('base64'), count: topics.length } }];

const lines = String($input.first().json.stdout || '').split('\n').filter(l => l.trim().startsWith('{'));
let r;
try { r = JSON.parse(lines[lines.length - 1]); } catch (e) { r = { go: false, why: 'pick step gave no answer: ' + String($input.first().json.stderr || '').slice(-200) }; }
return [{ json: r }];

